def match_fault_pattern(alarm_code, symptoms):
    """匹配故障模式"""
    patterns = graph.query(f"MATCH (p:Phenomenon)-[:contains]->(sp:SubPhenomenon) WHERE p.code = '{alarm_code}' RETURN sp")
    return rank_by_similarity(patterns, symptoms)

def calc_repair_priority(severity, equipment_class, production_impact):
    weights = {"CRITICAL": 1.0, "HIGH": 0.8, "MEDIUM": 0.5, "LOW": 0.2}
    score = weights.get(severity, 0.5) * 0.4 + equipment_class * 0.3 + production_impact * 0.3
    return "P1" if score > 0.8 else "P2" if score > 0.5 else "P3"

def generate_checkpoint_list(phenomenon_id):
    checkpoints = graph.query(
        f"MATCH (p:Phenomenon)-[:needs_check]->(cp:Checkpoint) WHERE p.id = '{phenomenon_id}' RETURN cp ORDER BY cp.priority"
    )
    return [{"step": i+1, "name": cp.label, "method": cp.method} for i, cp in enumerate(checkpoints)]
